<?php
/** Combined policy3 username invitation -> table/file ACL -> revoke -> deletion lifecycle. No SMTP or live users. */
umask(0077);require '/var/www/app/app/common.php';if(session_status()===PHP_SESSION_ACTIVE){session_abort();}
if(!defined('FAMILYHUB_DEVELOPMENT_MODE')||FAMILYHUB_DEVELOPMENT_MODE!==true){throw new RuntimeException('Synthetic only');}
use Kanboard\Plugin\FamilyHub\Model\NativeService;use Kanboard\Plugin\FamilyHub\Model\NativeError;
$pdo=$container['db']->getConnection();$service=new NativeService($container);$checks=0;$prefix='combined_'.bin2hex(random_bytes(5));$ip='combined-'.bin2hex(random_bytes(6));$password=bin2hex(random_bytes(16));
function check($v,$m){global$checks;if(!$v)throw new RuntimeException('FAIL: '.$m);$checks++;echo 'PASS: '.$m.PHP_EOL;}
function api($op,$p=[],$token=''){global$service,$ip;return $service->dispatch($op,$p,$token?'Bearer '.$token:'',$ip);}
function q($sql,$p=[]){global$pdo;$s=$pdo->prepare($sql);$s->execute($p);$r=$s->fetchAll(PDO::FETCH_ASSOC);$s->closeCursor();return$r;}
function uuid(){$h=bin2hex(random_bytes(16));return substr($h,0,8).'-'.substr($h,8,4).'-4'.substr($h,13,3).'-a'.substr($h,17,3).'-'.substr($h,20);}
function deny($op,$p,$token,$code){try{api($op,$p,$token);$ok=false;}catch(NativeError$e){$ok=$e->errorCode===$code;}check($ok,$op.' denies '.$code);}
function user($suffix){global$container,$prefix,$password;$container['userModel']->create(['username'=>$prefix.'_'.$suffix,'password'=>$password,'role'=>'app-user']);$u=api('auth.login',['username'=>$prefix.'_'.$suffix,'password'=>$password,'deviceName'=>'Combined documents']);api('moderation.acceptPolicy',['policyVersion'=>1],$u['token']);return$u;}
function invitation($scope,$target,$owner,$role='member'){return api('invitations3.create',['scopeId'=>$scope['id'],'recipient'=>$target['user']['username'],'role'=>$role,'accessScope'=>'space','language'=>'en','requestId'=>uuid()],$owner['token'])['invitation'];}
function table($scope,$u,$title){return api('tables.create',['scopeId'=>$scope['id'],'id'=>uuid(),'title'=>$title,'requestId'=>uuid()],$u['token'])['sheet'];}
function upload($scope,$table,$u,$bytes){$t=['scopeId'=>$scope['id'],'targetType'=>'table','targetId'=>$table['id']];$id=uuid();api('attachments.begin',$t+['id'=>$id,'name'=>'shared.txt','mime'=>'text/plain','size'=>strlen($bytes),'sha256'=>hash('sha256',$bytes),'requestId'=>uuid()],$u['token']);api('attachments.chunk',$t+['id'=>$id,'offset'=>0,'dataBase64'=>base64_encode($bytes)],$u['token']);api('attachments.complete',$t+['id'=>$id,'requestId'=>uuid()],$u['token']);return$t+['id'=>$id];}
$owner=user('owner');$member=user('member');$viewer=user('viewer');$outsider=user('outsider');$scope=api('scopes.create',['id'=>uuid(),'kind'=>'organization','name'=>'Combined document sharing','accessPolicyVersion'=>3,'requestId'=>uuid()],$owner['token'])['scope'];$sheet=table($scope,$owner,'Owner table');$base=['scopeId'=>$scope['id'],'id'=>$sheet['id']];$file=upload($scope,$sheet,$owner,"Shared content\n");
$pending=invitation($scope,$member,$owner);check($pending['recipientEmail']===null,'combined recipient is account-bound username without email');deny('tables.get',$base,$member['token'],'permission_revoked');deny('attachments.get',$file,$member['token'],'permission_revoked');check(count(api('invitations3.pending',[],$member['token'])['invitations'])===1,'new username invitation discoverable before membership');api('invitations3.accept',['invitationId'=>$pending['id']],$member['token']);check(api('tables.get',$base,$member['token'])['sheet']['title']==='Owner table','explicit acceptance grants organization table read');check(base64_decode(api('attachments.get',$file,$member['token'])['dataBase64'])==="Shared content\n",'explicit acceptance grants private file bytes');
$viewInvite=invitation($scope,$viewer,$owner,'viewer');api('invitations3.accept',['invitationId'=>$viewInvite['id']],$viewer['token']);check(api('tables.get',$base,$viewer['token'])['sheet']['id']===$sheet['id'],'invited viewer reads same table');deny('tables.acquire',$base+['requestId'=>uuid()],$viewer['token'],'permission_revoked');deny('attachments.get',$file,$outsider['token'],'permission_revoked');
$lease=api('tables.acquire',$base+['requestId'=>uuid()],$member['token'])['lease'];api('scopes.removeMember',['scopeId'=>$scope['id'],'userId'=>$member['user']['id'],'requestId'=>uuid()],$owner['token']);deny('tables.renew',$base+['token'=>$lease['token'],'requestId'=>uuid()],$member['token'],'permission_revoked');deny('attachments.get',$file,$member['token'],'permission_revoked');
$next=invitation($scope,$member,$owner);api('invitations3.accept',['invitationId'=>$next['id']],$member['token']);$contribution=table($scope,$member,'Retained member table');$retained=upload($scope,$contribution,$member,"Retained contribution\n");$pendingAgain=invitation($scope,$member,$owner);deny('account.deletion.preview',[],$member['token'],'client_upgrade_required');$plan=api('account.deletion.preview',['policyVersion'=>3],$member['token']);check($plan['impact']['sharedTablesRetainedIfScopeKept']===1&&$plan['impact']['sharedAttachmentsRetainedIfScopeAndTargetKept']===1,'deletion preview counts invited member shared table/file retention');$deleted=api('account.deletion.confirm',['operationId'=>uuid(),'receiptToken'=>bin2hex(random_bytes(32)),'previewHash'=>$plan['previewHash'],'password'=>$password,'confirmation'=>'DELETE','policyVersion'=>3],$member['token']);check($deleted['deleted'],'invited contributor deletion completes without deleting others organization');check(q('SELECT id FROM familyhub_invitations WHERE id=?',[$pendingAgain['id']])===[],'deletion removes account-bound pending invitation');$row=q('SELECT created_by,lease_hash FROM familyhub_tables WHERE scope_id=? AND id=?',[$scope['id'],$contribution['id']])[0];check($row['created_by']===''&&$row['lease_hash']===null,'retained table loses deleted author and lease binding');check(base64_decode(api('attachments.get',$retained,$viewer['token'])['dataBase64'])==="Retained contribution\n",'other accepted viewer retains exact shared bytes after account deletion');$row=q('SELECT owner_account_id,owner_device_id FROM familyhub_attachments WHERE scope_id=? AND id=?',[$scope['id'],$retained['id']])[0];check($row['owner_account_id']===''&&$row['owner_device_id']==='','retained private storage metadata removes deleted account/device');
$recreated=user('member');check(api('invitations3.pending',[],$recreated['token'])['invitations']===[],'recreated username inherits no invitation');deny('tables.get',['scopeId'=>$scope['id'],'id'=>$contribution['id']],$recreated['token'],'permission_revoked');deny('attachments.get',$retained,$recreated['token'],'permission_revoked');
echo 'SUCCESS '.$checks.' combined sharing/document lifecycle checks ('.$pdo->getAttribute(PDO::ATTR_DRIVER_NAME).')'.PHP_EOL;
